/**
 * HARDWARE DOG / TV SKINS
 *
 * A skin is a picture of a TV and its mapping profile: where the screen
 * opening is, where POWER, the dial and the handle are, all normalized to
 * 0..1 of the picture so alignment holds at any size. The component never
 * hard-codes a coordinate: a new TV is a new picture + a new profile,
 * generated by web/scripts/build-brand-assets.mjs, and a new SpriteSet if
 * it wants another character. The engine stays the same.
 *
 *   TURQUOISE   Hardware Dog's TV, the dog: every section but Flipper Lab
 *   ORANGE      Flipper Lab's TV, its companion
 */

import type { CompanionProfile } from '../../core/lab/companion';
import profileJson from '../../../../assets/brand/web/hd-tv-orange.profile.json';
import frame1x from '../../../../assets/brand/web/hd-tv-orange-560.webp';
import frame2x from '../../../../assets/brand/web/hd-tv-orange-1120.webp';
import turquoiseJson from '../../../../assets/brand/web/hd-tv-turquoise.profile.json';
import turquoise1x from '../../../../assets/brand/web/hd-tv-turquoise-560.webp';
import turquoise2x from '../../../../assets/brand/web/hd-tv-turquoise-1120.webp';

export interface Box {
  x: number;
  y: number;
  w: number;
  h: number;
}
export interface Ellipse {
  cx: number;
  cy: number;
  rx: number;
  ry: number;
}

export interface TvProfile {
  id: string;
  version: number;
  reference: { width: number; height: number; ratio: number };
  screen: { box: Box; polygon: [number, number][] };
  power: Box;
  dial: Ellipse;
  knob: Ellipse;
  handle: Box;
  speaker: Box;
  logo: Box;
}

export interface TvSkin {
  profile: TvProfile;
  frame: { src: string; srcset: string };
  /** The dial angle (degrees) for each view, in DIAL_MODES order. */
  dialAngles: readonly number[];
}

/** Checks a profile before it is used: a bad file fails loudly, not misaligned. */
export function checkProfile(p: TvProfile): TvProfile {
  const inUnit = (v: number) => Number.isFinite(v) && v >= 0 && v <= 1;
  const box = (b: Box, name: string) => {
    if (![b.x, b.y, b.w, b.h].every(inUnit) || b.x + b.w > 1.0001 || b.y + b.h > 1.0001) throw new Error(`TV profile: ${name} is outside the picture`);
  };
  if (!(p.reference.width > 0 && p.reference.height > 0)) throw new Error('TV profile: reference size');
  if (p.screen.polygon.length < 8 || !p.screen.polygon.every(([x, y]) => inUnit(x) && inUnit(y))) throw new Error('TV profile: screen polygon');
  box(p.screen.box, 'screen');
  box(p.power, 'power');
  box(p.handle, 'handle');
  for (const [name, e] of [
    ['dial', p.dial],
    ['knob', p.knob],
  ] as const)
    if (![e.cx, e.cy, e.rx, e.ry].every(inUnit)) throw new Error(`TV profile: ${name}`);
  return p;
}

export const ORANGE_TV: TvSkin = {
  profile: checkProfile(profileJson as unknown as TvProfile),
  frame: { src: frame1x, srcset: `${frame1x} 560w, ${frame2x} 1120w` },
  dialAngles: [0, 42, 84],
};

export const TURQUOISE_TV: TvSkin = {
  profile: checkProfile(turquoiseJson as unknown as TvProfile),
  frame: { src: turquoise1x, srcset: `${turquoise1x} 560w, ${turquoise2x} 1120w` },
  dialAngles: [0, 42, 84],
};

/** The TV of a profile. */
export const skinFor = (profile: CompanionProfile): TvSkin => (profile === 'flipper' ? ORANGE_TV : TURQUOISE_TV);

const pct = (v: number) => `${(v * 100).toFixed(3)}%`;

/** CSS for a box of the profile: absolute, in percent of the TV. */
export const boxStyle = (b: Box) => ({ left: pct(b.x), top: pct(b.y), width: pct(b.w), height: pct(b.h) });
export const ellipseStyle = (e: Ellipse) => ({ left: pct(e.cx - e.rx), top: pct(e.cy - e.ry), width: pct(e.rx * 2), height: pct(e.ry * 2) });

/**
 * The screen opening as a clip-path, relative to the screen box: content
 * and CRT effects stay inside the opening at every size.
 */
export function screenClip(p: TvProfile): string {
  const { box, polygon } = p.screen;
  return `polygon(${polygon.map(([x, y]) => `${pct((x - box.x) / box.w)} ${pct((y - box.y) / box.h)}`).join(', ')})`;
}

/** The screen opening as an SVG path in profile units (developer overlay). */
export function screenPath(p: TvProfile): string {
  return `M${p.screen.polygon.map(([x, y]) => `${(x * 1000).toFixed(1)} ${(y * 1000).toFixed(1)}`).join(' L')} Z`;
}
